-- READ ONLY. Catalog definitions and effective privileges only; no application rows.
SELECT jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m','f')),
 'columns',(SELECT jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'name',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default) ORDER BY table_schema,table_name,ordinal_position) FROM information_schema.columns WHERE table_schema IN ('public','private')),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated) ORDER BY n.nspname,c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private')),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) ORDER BY schemaname,tablename,indexname) FROM pg_indexes WHERE schemaname IN ('public','private')),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname) FROM pg_policies p WHERE schemaname IN ('public','private')),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'body_md5',md5(replace(p.prosrc,chr(13),'')),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'type',t.tgtype,'function',pn.nspname||'.'||p.proname) ORDER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE NOT t.tgisinternal AND n.nspname IN ('public','private')),
 'table_privileges',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'role',r.role_name,'select',has_table_privilege(r.role_name,c.oid,'SELECT'),'insert',has_table_privilege(r.role_name,c.oid,'INSERT'),'update',has_table_privilege(r.role_name,c.oid,'UPDATE'),'delete',has_table_privilege(r.role_name,c.oid,'DELETE'),'truncate',has_table_privilege(r.role_name,c.oid,'TRUNCATE'),'references',has_table_privilege(r.role_name,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.role_name,c.oid,'TRIGGER'),'any_column_select',has_any_column_privilege(r.role_name,c.oid,'SELECT'),'any_column_update',has_any_column_privilege(r.role_name,c.oid,'UPDATE')) ORDER BY n.nspname,c.relname,r.role_name) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES ('anon'),('authenticated')) r(role_name) WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m','f')),
 'private_schema_privileges',(SELECT jsonb_agg(jsonb_build_object('role',r.role_name,'usage',has_schema_privilege(r.role_name,'private','USAGE'),'create',has_schema_privilege(r.role_name,'private','CREATE')) ORDER BY r.role_name) FROM (VALUES ('anon'),('authenticated')) r(role_name))
) AS metadata;
